use std::fmt::Write as _;

use super::*;
use crate::native::registry::Plugin;

pub(crate) fn rust_registrant(registry: &Registry, target: Target) -> Result<String> {
	let mut rust = String::from(
		"// Generated by leptoskit. Edit native.plugins and Cargo dependencies \
		 instead.\n#[unsafe(no_mangle)]\npub unsafe extern \"C\" fn \
		 leptoskit_app_create_with_context(wasm: *const u8, len: usize, context: *const \
		 leptoskit_bridge_ffi::app::NativeAppContext, error: *mut leptoskit_bridge_ffi::Buffer) \
		 -> *mut leptoskit_bridge_ffi::app::App {\n    // SAFETY: The native app owns these \
		 input/output buffers for this call.\n    unsafe { \
		 leptoskit_bridge_ffi::app::create_with_context(wasm, len, context, error, |",
	);
	rust.push_str(
		if registry
			.plugins
			.iter()
			.any(|plugin| plugin.rust_type.is_some() || plugin.rust_factory.is_some())
		{
			"app"
		} else {
			"_app"
		},
	);
	rust.push_str(", _context| {\n");

	for plugin in &registry.plugins {
		register_plugin(&mut rust, plugin, target)?;
	}

	rust.push_str("        Ok(())\n    }) }\n}\n");

	Ok(rust)
}

/// Rust and platform implementations are exclusive; retain the configured
/// owner.
fn register_plugin(rust: &mut String, plugin: &Plugin, target: Target) -> Result<()> {
	let install = if plugin.rust_worker {
		"install_worker"
	} else {
		"install"
	};

	if let Some(kind) = &plugin.rust_type {
		writeln!(
			rust,
			"        app.{install}(Box::new({}::{kind}::default()))?;",
			plugin.crate_name
		)?;

		return Ok(());
	}

	if let Some(factory) = &plugin.rust_factory {
		return register_factory(rust, plugin, factory, install);
	}

	let supported = match target {
		Target::Ios | Target::IosSimulator | Target::Macos => {
			plugin.apple_module.is_some() && plugin.apple_type.is_some()
		}
		Target::Android | Target::AndroidX86_64 => plugin.android_type.is_some(),
		Target::Harmonyos | Target::HarmonyosX86_64 | Target::Windows | Target::Linux => false,
	};

	anyhow::ensure!(
		supported,
		"plugin {} has no implementation for {target:?}",
		plugin.name
	);

	Ok(())
}

fn register_factory(
	rust: &mut String,
	plugin: &Plugin,
	factory: &str,
	install: &str,
) -> Result<()> {
	if plugin.rust_async {
		let options = plugin
			.options_json
			.as_ref()
			.context("validated async plugin options missing")?;
		writeln!(
			rust,
			"        app.install_async(std::sync::Arc::new({}::{factory}({options:?})?))?;",
			plugin.crate_name
		)?;
	} else {
		writeln!(
			rust,
			"        app.{install}(Box::new({}::{factory}(&_context.data_dir, \
			 &_context.cache_dir)?))?;",
			plugin.crate_name
		)?;
	}

	Ok(())
}
